251	+  protected auswahlUmschalten(code: string): void {
252	+    const naechste = new Set(this.ausgewaehlteCodes());
253	+    naechste.has(code) ? naechste.delete(code) : naechste.add(code);
254	+    this.ausgewaehlteCodes.set(naechste);
255	+  }
