257	+  protected istFokussiert(reihe: string, spalte: number): boolean {
258	+    const f = this.fokussiertePosition();
259	+    return f !== null && f.reihe === reihe && f.spalte === spalte;
260	+  }
261	+
262	+  protected onSitzplanKeydown(event: KeyboardEvent): void {
263	+    const plan = this.sitzplan();
264	+    const aktuell = this.fokussiertePosition();
265	+    if (!plan || !aktuell) return;
266	+
267	+    switch (event.key) {
268	+      case 'ArrowRight':
269	+        event.preventDefault();
270	+        this.bewegeHorizontal(plan, aktuell, 1);
271	+        break;
272	+      case 'ArrowLeft':
273	+        event.preventDefault();
274	+        this.bewegeHorizontal(plan, aktuell, -1);
275	+        break;
276	+      case 'ArrowDown':
277	+        event.preventDefault();
278	+        this.bewegeVertikal(plan, aktuell, 1);
279	+        break;
280	+      case 'ArrowUp':
281	+        event.preventDefault();
282	+        this.bewegeVertikal(plan, aktuell, -1);
283	+        break;
284	+      case ' ':
285	+      case 'Enter':
286	+        event.preventDefault();
287	+        this.aktiviereFokussiertePosition(plan, aktuell);
288	+        break;
289	+    }
290	+  }
291	+
292	+  private aktiviereFokussiertePosition(plan: Sitzplan, aktuell: Position): void {
293	+    const reihe = plan.reihen.find((r) => r.reihe === aktuell.reihe);
294	+    const position = reihe?.positionen.find((p) => p.spalte === aktuell.spalte);
295	+    if (!position || position.status === 'Belegt' || !position.code) return;
296	+    this.auswahlUmschalten(position.code);
297	+  }
298	+
299	+  private bewegeHorizontal(plan: Sitzplan, aktuell: Position, richtung: 1 | -1): void {
300	+    const reihe = plan.reihen.find((r) => r.reihe === aktuell.reihe);
301	+    if (!reihe) return;
302	+    let spalte = aktuell.spalte + richtung;
303	+    while (spalte >= 1 && spalte <= reihe.positionen.length) {
304	+      const position = reihe.positionen.find((p) => p.spalte === spalte);
305	+      if (position?.typ === 'Sitzplatz') {
306	+        this.setzeFokus({ reihe: aktuell.reihe, spalte });
307	+        return;
308	+      }
309	+      spalte += richtung;
310	+    }
311	+  }
312	+
313	+  private bewegeVertikal(plan: Sitzplan, aktuell: Position, richtung: 1 | -1): void {
314	+    const rowIndex = plan.reihen.findIndex((r) => r.reihe === aktuell.reihe);
315	+    const naechsterIndex = rowIndex + richtung;
316	+    if (naechsterIndex < 0 || naechsterIndex >= plan.reihen.length) return;
317	+    const naechsteReihe = plan.reihen[naechsterIndex];
318	+    const position = naechsteReihe.positionen.find((p) => p.spalte === aktuell.spalte);
319	+    if (!position) return;
320	+    this.setzeFokus({ reihe: naechsteReihe.reihe, spalte: aktuell.spalte });
321	+  }
322	+
323	+  private setzeFokus(position: Position): void {
324	+    this.fokussiertePosition.set(position);
325	+    const code = `${position.reihe}${position.spalte}`;
326	+    (
327	+      this.sitzplanRef()?.nativeElement.querySelector(`[data-code="${code}"]`) as HTMLElement | null
328	+    )?.focus();
329	+  }
330	+
331	+  private ersteSitzplatzPosition(plan: Sitzplan): Position | null {
332	+    for (const reihe of plan.reihen) {
333	+      const position = reihe.positionen.find((p: SitzplanPosition) => p.typ === 'Sitzplatz');
334	+      if (position) return { reihe: reihe.reihe, spalte: position.spalte };
335	+    }
336	+    return null;
337	+  }
338	 }
